class Solution {
  public long maximumScoreAfterOperations(int[][] edges, int[] values) {
    int n = values.length;
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(e[1]);
      graph[e[1]].add(e[0]);
    }
    int[] order = new int[n], parent = new int[n];
    Arrays.fill(parent, -1);
    int size = 0;
    order[size++] = 0;
    for (int i = 0; i < size; i++) {
      for (int v : graph[order[i]]) {
        if (v != parent[order[i]]) {
          parent[v] = order[i];
          order[size++] = v;
        }
      }
    }
    long total = 0;
    for (int v : values) total += v;
    // keep[u]: the least value that must stay in u's subtree so every root-to-leaf path is non-zero
    long[] keep = new long[n], childSum = new long[n];
    boolean[] hasChild = new boolean[n];
    for (int i = n - 1; i >= 0; i--) {
      int u = order[i];
      keep[u] = hasChild[u] ? Math.min(values[u], childSum[u]) : values[u];
      if (parent[u] >= 0) {
        childSum[parent[u]] += keep[u];
        hasChild[parent[u]] = true;
      }
    }
    return total - keep[0];
  }
}
